import {ToolRegistry} from './registry.js';

describe('ToolRegistry dynamic schemas', () => {
  it('rejects Paris after the current schema requires a number (specs/hal-engine-tool-input-validation/spec.md#8)', async () => {
    const registry = new ToolRegistry();
    const stringSchema = {type: 'object', properties: {location: {type: 'string'}}};
    const numberSchema = {type: 'object', properties: {location: {type: 'number'}}};
    let inputSchema = stringSchema;
    const received: Record<string, unknown>[] = [];
    registry.register(
      () => ({name: 'weather', description: 'Get weather', inputSchema}),
      async input => {
        received.push(input);
        return JSON.stringify(input);
      }
    );

    await registry.execute('weather', {location: 'Paris'});
    inputSchema = numberSchema;
    const rejection = await registry.execute('weather', {location: 'Paris'});
    inputSchema = stringSchema;
    await registry.execute('weather', {location: 'Berlin'});

    expect(rejection.result).toMatch(/location.*number/);
    expect(received).toEqual([{location: 'Paris'}, {location: 'Berlin'}]);
  });
});
EOF
